// Identity and URL helpers shared by pages, the markdown renderer and feeds.
// Kept free of Node imports so client components can use it too.

export const SITE = {
  name: "정상기",
  handle: "토비라이프",
  email: "happytobilife@gmail.com",
  origin: "https://tobilife.github.io",
  basePath: "/profile",
  careerStart: "2009-03",
} as const;

/** Default share image, generated by src/app/og.png/route.tsx. */
export const DEFAULT_OG_IMAGE = "/og.png";

/** Prefixes a site-relative path ("/blog/") with the base path. Other URLs pass through. */
export function withBase(path: string): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const base = SITE.basePath;
  if (path === base || path.startsWith(base + "/")) return path;
  return base + path;
}

/** The public URL of a site-relative path, for feeds, sitemaps and Open Graph tags. */
export function absoluteUrl(path: string): string {
  return SITE.origin + withBase(path);
}
